package com.aistock.market.realization;
import com.aistock.market.forecast.ForecastCandidate;import com.aistock.market.quotation.*;import com.aistock.common.BusinessException;import java.time.*;import java.util.*;import java.math.BigDecimal;import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;import static com.aistock.market.realization.RealizationRecords.*;
class RealizationValidatorTest {
 final Clock clock=Clock.fixed(Instant.parse("2026-09-25T14:00:00Z"),ZoneOffset.UTC);final LocalDate origin=LocalDate.parse("2026-09-21");final List<LocalDate> targets=List.of("2026-09-22","2026-09-23","2026-09-24","2026-09-25","2026-09-28").stream().map(LocalDate::parse).toList();
 Request request(){return new Request(UUID.randomUUID(),"SH600030",origin,targets,targets.get(3),clock.instant().plusSeconds(90));}
 RawBar bar(LocalDate d,int status){return new RawBar(d,BigDecimal.TEN,BigDecimal.TEN,BigDecimal.TEN,BigDecimal.TEN,BigDecimal.ZERO,BigDecimal.ZERO,status,null);}
 Head head(){return new Head(UUID.randomUUID().toString(),"a".repeat(64),List.of(bar(origin,1),bar(targets.get(0),0),bar(targets.get(1),1)));}
 ForecastCandidate candidate(Request r,Head h){var calendar=new ArrayList<TradingDay>();for(var d=origin;!d.isAfter(r.dueThrough().plusDays(5));d=d.plusDays(1))calendar.add(new TradingDay(d,d.getDayOfWeek().getValue()<6&&!d.equals(targets.get(3))));return new ForecastCandidate(r.operationId().toString(),r.instrumentId(),h.versionId(),"baostock",DEFINITION,clock.instant(),"b".repeat(64),h.bars().stream().map(b->new ForecastCandidate.PairedBar(b,BigDecimal.TEN)).toList(),calendar);}
 @Test void dueStatusSeparatesSuspensionMissingCalendarAndFuture(){var r=request();var h=head();var v=new RealizationValidator(clock,20);var e=v.evidence(r,h,candidate(r,h));assertEquals(List.of("SUSPENDED","VERIFIED","MISSING","CALENDAR_CHANGED"),e.observations().stream().map(Day::state).toList());assertEquals(4,e.observations().size());assertEquals("10",e.observations().get(0).rawClose());assertNull(e.observations().get(2).rawClose());}
 @Test void cutoffIdentityAndOriginAreStrict(){var r=request();var h=head();var v=new RealizationValidator(clock,20);var early=new RealizationValidator(Clock.fixed(Instant.parse("2026-09-25T11:59:00Z"),ZoneOffset.UTC),20);assertThrows(BusinessException.class,()->early.request(r));var c=candidate(r,h);var wrong=new ForecastCandidate(c.operationId(),c.instrumentId(),UUID.randomUUID().toString(),c.provider(),c.definition(),c.fetchedAt(),c.sourcePayloadHash(),c.bars(),c.calendar());assertThrows(BusinessException.class,()->v.evidence(r,h,wrong));var noOrigin=new Head(h.versionId(),h.contentHash(),h.bars().subList(1,3));assertThrows(BusinessException.class,()->v.evidence(r,noOrigin,candidate(r,noOrigin)));}
}
